mapper.update:
update cm_syllabus_version
set published_date = #{publishedDate}, update_by = #{userId}, update_time = now()
where id = #{syllabusVersionId}

mapper.insert:
insert into cm_idempotency_record(
    id, action_code, request_id, payload_hash, status, resource_type, resource_id, expires_time
) values (
    #{id}, #{action}, #{requestId}, #{payloadHash}, 'processing', 'syllabus_version', #{resourceId}, #{expiresTime}
)
on conflict (action_code, request_id) do nothing

mapper.select:
select count(*) from cm_import_batch
where syllabus_version_id = #{syllabusVersionId}
  and status = 'importing'

select distinct object_key from (
    select source_file_path as object_key from cm_syllabus_version where id = #{syllabusVersionId}
    union
    select source_file_path as object_key from cm_document where syllabus_version_id = #{syllabusVersionId}
    union
    select batch.source_file_path as object_key
    from cm_import_batch batch
    left join cm_document document on document.id = batch.document_id
    where batch.syllabus_version_id = #{syllabusVersionId}
       or document.syllabus_version_id = #{syllabusVersionId}
) storage_objects where coalesce(trim(object_key), '') <> ''

mapper.delete:
delete from cm_knowledge_import_diff
where import_batch_id in (
    select id from cm_import_batch where syllabus_version_id = #{syllabusVersionId}
)
